const listOrchestrationAccessGrantExpiryCandidates = `-- name: ListOrchestrationAccessGrantExpiryCandidates :many
SELECT grant_id, revision, expires_at
FROM orchestration_access_grants
WHERE status = 'active'
  AND (julianday(expires_at) IS NULL OR julianday(expires_at) <= julianday(CAST(?1 AS TEXT)))
ORDER BY julianday(expires_at) ASC, grant_id ASC
LIMIT ?2
`

type ListOrchestrationAccessGrantExpiryCandidatesParams struct {
	NowAt string `db:"now_at" json:"now_at"`
	Limit int64  `db:"limit" json:"limit"`
}

type ListOrchestrationAccessGrantExpiryCandidatesRow struct {
	GrantID   string `db:"grant_id" json:"grant_id"`
	Revision  int64  `db:"revision" json:"revision"`
	ExpiresAt string `db:"expires_at" json:"expires_at"`
}

// This query is intentionally narrow: expiry ownership only needs the grant
// id, current revision, and immutable expiry instant.  The caller supplies
// the security-time snapshot and a hard row bound; SQLite wall clock is never
// consulted for candidate selection.
func (q *Queries) ListOrchestrationAccessGrantExpiryCandidates(ctx context.Context, arg ListOrchestrationAccessGrantExpiryCandidatesParams) ([]ListOrchestrationAccessGrantExpiryCandidatesRow, error) {
	rows, err := q.db.QueryContext(ctx, listOrchestrationAccessGrantExpiryCandidates, arg.NowAt, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOrchestrationAccessGrantExpiryCandidatesRow{}
	for rows.Next() {
		var i ListOrchestrationAccessGrantExpiryCandidatesRow
		if err := rows.Scan(&i.GrantID, &i.Revision, &i.ExpiresAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

